/** Decodes one RLE frame into a flat string of length BOND_W * BOND_H. */
export function decodeBondFrame(rle: string): string {
  let out = "";
  for (let i = 0; i < rle.length; i++) {
    if (rle[i] === "~" && i + 2 < rle.length) {
      const c = rle.charCodeAt(i + 1);
      const count = c >= 97 ? c - 87 : c - 48;
      out += rle[i + 2].repeat(count);
      i += 2;
    } else {
      out += rle[i];
    }
  }
  return out;
}
